function normalizeInstancePath(rawPath) {
  const trimmed = rawPath.replace(/^[/.]/, '');
  return trimmed.replace(/\//g, '.');
}

function formatErrorPath(err) {
  const basePath = normalizeInstancePath(err.instancePath ?? err.dataPath ?? '');
  const missing = err.params.missingProperty;
  if (err.keyword === 'required' && typeof missing === 'string') {
    return basePath ? \`\${basePath}.\${missing}\` : missing;
  }
  return basePath || 'input';
}

function formatSchemaErrors(name, errors) {
  const details = (errors ?? []).map(err => \`\${formatErrorPath(err)} \${err.message ?? 'is invalid'}\`);
  return JSON.stringify({
    error: \`Invalid input for tool \"\${name}\": \${details.join('; ')}\`,
  });
}

